      "    ///",
      "    /// Division is multiplication by the multiplicative inverse.",
      "    pub fn div(c: &BigUint, d: &BigUint, p: &BigUint) -> BigUint {",
      "        let d_inv = Self::inverse_mul(d, p);",
      "        Self::mul(c, &d_inv, p)",
      "    }",
